package solution

import (
	"reflect"
	"testing"
)

func TestClosestSpanNormalAndUnsorted(t *testing.T) {
	low, high, ok := ClosestSpan([]int{10, 3, 20, 8})
	if !ok || low != 8 || high != 10 {
		t.Fatalf("ClosestSpan returned (%d, %d, %v), want (8, 10, true)", low, high, ok)
	}
}

func TestClosestSpanChoosesLexicographicallySmallestTie(t *testing.T) {
	low, high, ok := ClosestSpan([]int{8, 10, 4, 6})
	if !ok || low != 4 || high != 6 {
		t.Fatalf("ClosestSpan tie returned (%d, %d, %v), want (4, 6, true)", low, high, ok)
	}
}

func TestClosestSpanDuplicateTieUsesSmallestPair(t *testing.T) {
	low, high, ok := ClosestSpan([]int{2, 2, 1, 1})
	if !ok || low != 1 || high != 1 {
		t.Fatalf("duplicate tie returned (%d, %d, %v), want (1, 1, true)", low, high, ok)
	}
}

func TestClosestSpanFewerThanTwoValues(t *testing.T) {
	for _, values := range [][]int{nil, {}, {42}} {
		low, high, ok := ClosestSpan(values)
		if low != 0 || high != 0 || ok {
			t.Fatalf("ClosestSpan(%v) = (%d, %d, %v), want (0, 0, false)", values, low, high, ok)
		}
	}
}

func TestClosestSpanDoesNotMutateInput(t *testing.T) {
	for _, input := range [][]int{{3, 1, 2}, {1, 2, 3}} {
		original := append([]int(nil), input...)
		_, _, _ = ClosestSpan(input)
		if !reflect.DeepEqual(input, original) {
			t.Fatalf("input mutated: got %v, want %v", input, original)
		}
	}
}

